-- Local-only replacement of Cloud visibility: fictional dossiers remain excluded in Cloud.
CREATE FUNCTION public.is_entrepreneur_visible_dompe(_s submissions) RETURNS boolean LANGUAGE sql AS $$ SELECT _s.request_type='remblai' AND _s.parcours_direction='reception' $$;
-- Local structural fixture only. No production contacts, provider, cron or notification worker.
CREATE TABLE material_offers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now(),source_type text DEFAULT 'admin_manual',source_id uuid,owner_user_id uuid,status text DEFAULT 'ready_for_matching',qualification_status text DEFAULT 'qualified',raw_description text,quantity_value numeric,quantity_unit text,quantity_approximate boolean DEFAULT false,trip_count integer,vehicle_type text,principal_material text,secondary_materials text[] DEFAULT '{}',trace_materials text[] DEFAULT '{}',granulometry_min_inches numeric,granulometry_max_inches numeric,granulometry_approximate boolean DEFAULT false,declared_clean boolean,declared_contaminated boolean,environmental_status text DEFAULT 'characterized',location_raw text,address text,sector text,city text,region text,latitude float8,longitude float8,geocoding_source text,availability_start date,availability_end date,max_radius_km numeric,notes text,parser_confidence numeric,parser_version text);
ALTER TABLE trips ADD COLUMN delivered_at timestamptz;
CREATE TABLE request_followups(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),entity_type text,entity_id uuid,follow_status text DEFAULT 'nouvelle',next_action text,reminder_reason text,next_reminder_at timestamptz,resolved_at timestamptz,UNIQUE(entity_type,entity_id));
CREATE TABLE request_followup_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),followup_id uuid REFERENCES request_followups(id),entity_type text,entity_id uuid,action text,detail jsonb DEFAULT '{}',created_at timestamptz DEFAULT now());
CREATE TABLE crm_notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),dedupe_key text UNIQUE,entity_type text,entity_id uuid,body text);
CREATE FUNCTION crm_notify(text,text,text,text,text,text,text,uuid,text,text,text,timestamptz,jsonb,boolean) RETURNS uuid LANGUAGE plpgsql AS $$ DECLARE i uuid;BEGIN INSERT INTO crm_notifications(dedupe_key,entity_type,entity_id,body) VALUES($1,$7,$8,$6) ON CONFLICT(dedupe_key) DO UPDATE SET body=excluded.body RETURNING id INTO i;RETURN i;END $$;
CREATE TABLE local_email_capture(id bigserial PRIMARY KEY,queue_name text,payload jsonb,created_at timestamptz DEFAULT now());
CREATE TABLE local_queue_failure(enabled boolean);INSERT INTO local_queue_failure VALUES(false);
CREATE FUNCTION enqueue_email(queue_name text,payload jsonb) RETURNS bigint LANGUAGE plpgsql AS $$ DECLARE n bigint;BEGIN IF EXISTS(SELECT 1 FROM local_queue_failure WHERE enabled) THEN RAISE EXCEPTION 'local_queue_failure';END IF;IF payload->>'to' !~ '\.invalid$' THEN RAISE EXCEPTION 'no_real_contact';END IF;INSERT INTO local_email_capture(queue_name,payload) VALUES(queue_name,payload) RETURNING id INTO n;RETURN n;END $$;